import json
from pathlib import Path

from hashutil import fast_hash

_CACHE_DIR = Path("cache")


def _cache_key(resource_id: str) -> str:
    return f"{fast_hash(resource_id)}.json"


def _read_cache(resource_id: str) -> dict | None:
    key = _cache_key(resource_id)
    path = _CACHE_DIR / key
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (FileNotFoundError, json.JSONDecodeError):
        return None


def _write_cache(resource_id: str, data: dict) -> None:
    _CACHE_DIR.mkdir(parents=True, exist_ok=True)
    key = _cache_key(resource_id)
    path = _CACHE_DIR / key
    path.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")


def _compute(resource_id: str) -> dict:
    catalog = json.loads(Path("catalog.json").read_text(encoding="utf-8"))
    entry = catalog.get(resource_id, {})
    return {
        "resource": resource_id,
        "tier": entry.get("tier", "standard"),
        "weight": sum(ord(char) for char in resource_id),
    }


def fetch(resource_id: str) -> dict:
    cached = _read_cache(resource_id)
    if cached is not None:
        return cached
    data = _compute(resource_id)
    _write_cache(resource_id, data)
    return data

