#!/usr/bin/env python3
"""Print the report filenames under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"
PATTERN = re.compile(r"^report-(\d+)\.txt$")


def main() -> None:
    files: list[tuple[int, str]] = []
    for name in os.listdir(REPORTS_DIR):
        m = PATTERN.match(name)
        if m:
            files.append((int(m.group(1)), name))

    files.sort(key=lambda pair: pair[0])

    for _, name in files:
        print(name)


if __name__ == "__main__":
    main()

