import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Extract the leading YYYY-MM-DD HH:MM:SS timestamp from a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f'Usage: python {sys.argv[0]} AS_OF', file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = as_of_dt.replace(hour=0, minute=0, second=0, microsecond=0)
    # 7 days before AS_OF, at midnight (start of day)
    cutoff_dt = cutoff_dt.replace(day=cutoff_dt.day - 7)

    keep: list[str] = []
    archive: list[str] = []

    with open('app.log') as f:
        for line in f:
            line = line.rstrip('\n')
            if not line:
                continue
            ts = parse_timestamp(line)
            if ts is not None and ts < cutoff_dt:
                archive.append(line)
            else:
                keep.append(line)

    with open('app.log', 'w') as f:
        for line in keep:
            f.write(line + '\n')

    if archive:
        with open('archive.log', 'a') as f:
            for line in archive:
                f.write(line + '\n')


if __name__ == '__main__':
    main()

