import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a YYYY-MM-DD HH:MM:SS timestamp from the start of a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f'Usage: {sys.argv[0]} AS_OF', file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f'Error: AS_OF must be an integer Unix timestamp', file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    log_path = 'app.log'
    archive_path = 'archive.log'

    try:
        with open(log_path, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f'Error: {log_path} not found', file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append archived entries to archive.log (preserving order)
    if archive:
        with open(archive_path, 'a') as f:
            f.writelines(archive)

    # Rewrite app.log with remaining entries
    with open(log_path, 'w') as f:
        f.writelines(keep)

    print(f'Moved {len(archive)} entries to {archive_path}, kept {len(keep)} entries in {log_path}')


if __name__ == '__main__':
    main()

